mapper.select:
SELECT ROOM_ID, USER_ID, ADMIN_ID, STATUS, CREATED_AT, CLOSED_AT
FROM CHAT_ROOMS
WHERE ROOM_ID = #{roomId}

SELECT MESSAGE_ID, ROOM_ID, SENDER_ID, CONTENT, IS_READ, CREATED_AT
FROM CHAT_MESSAGES
WHERE MESSAGE_ID = #{messageId}

mapper.update:
UPDATE CHAT_MESSAGES
SET IS_READ = TRUE
WHERE ROOM_ID = #{roomId}
  AND SENDER_ID != #{readerId}
  AND IS_READ = FALSE

mapper.select:
SELECT COUNT(*)
FROM CHAT_MESSAGES
WHERE ROOM_ID = #{roomId}
  AND SENDER_ID != #{readerId}
  AND IS_READ = FALSE

SELECT cr.ROOM_ID, cr.USER_ID, u.NICKNAME, cr.ADMIN_ID, cr.STATUS, cr.CREATED_AT, cr.CLOSED_AT, (SELECT m.CONTENT FROM CHAT_MESSAGES m WHERE m.ROOM_ID = cr.ROOM_ID ORDER BY m.CREATED_AT DESC LIMIT 1) AS LAST_MESSAGE FROM CHAT_ROOMS cr INNER JOIN USERS u ON u.USER_ID = cr.USER_ID WHERE cr.STATUS = #{status}
AND cr.ROOM_ID > #{cursorId}
AND cr.ROOM_ID < #{cursorId}
AND (cr.CLOSED_AT, cr.ROOM_ID) < ( SELECT c2.CLOSED_AT, c2.ROOM_ID FROM CHAT_ROOMS c2 WHERE c2.ROOM_ID = #{cursorId} )
ORDER BY cr.ROOM_ID ASC ORDER BY cr.CLOSED_AT DESC, cr.ROOM_ID DESC ORDER BY cr.ROOM_ID DESC
LIMIT #{limit}

mapper.update:
UPDATE CHAT_ROOMS
SET STATUS = 'CLOSED', CLOSED_AT = CURRENT_TIMESTAMP
WHERE ROOM_ID = #{roomId}
  AND ADMIN_ID = #{adminId}
  AND STATUS = 'IN_PROGRESS'

UPDATE CHAT_ROOMS
SET STATUS = 'CLOSED', CLOSED_AT = CURRENT_TIMESTAMP
WHERE ROOM_ID = #{roomId}
AND USER_ID = #{userId}
AND STATUS IN ('WAITING', 'IN_PROGRESS')
